pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor, bytes32 hash1, bytes32 hash2, uint8 skipBlocks) public {
        // Keep the domain wide – any actor, any hashes, any non-negative block skip
        vm.assume(actor != address(0));

        // Fund the actor and the contract so lockInGuess can be called twice
        vm.deal(actor, 2 ether);
        vm.deal(address(c), 0 ether);

        // First successful lock
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(hash1);

        // Advance block number past the lock window to satisfy the requirement that
        // the first settle window has definitely passed (not strictly required, but keeps
        // the scenario realistic). Skip at least 1 block so block.number > stored block.
        vm.roll(block.number + (skipBlocks + 1));

        // Now try a second lock – the rule says it MUST revert because
        // guesses[actor].block is the old block number (non-zero).
        vm.prank(actor);
        (bool success, ) = address(c).call{value: 1 ether}(
            abi.encodeWithSignature("lockInGuess(bytes32)", hash2)
        );

        // The correct contract reverts a second lock (success == false).
        // The mutant allows it when the stored block happens to be 0 (which never occurs
        // here because we already set it to block.number+1 of the first call).
        assertTrue(!success);
    }
}

