pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(bytes32 hash, uint256 blockAdvance, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(blockAdvance >= 1);
        // fund the actor to call lockInGuess (needs 1 ether)
        vm.deal(actor, 1 ether);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(hash);
        // advance blocks so settle can be called
        vm.roll(block.number + blockAdvance);
        uint256 balBefore = address(c).balance;
        vm.prank(actor);
        c.settle();
        uint256 balAfter = address(c).balance;
        // reference settles: if the guess matches the blockhash answer, actor gets 2 ether => balance drops; mutant guess is always zero, so never matches (unless blockhash is zero) => balance unchanged.
        // The general rule: balance after settle <= balance before settle.
        // The mutant: if a hash == keccak256(abi.encodePacked(blockhash(guesses[actor].block))) the reference pays out, reducing balance, but the mutant does not, breaking the rule when hash!=0 and the answer matches.
        assertTrue(balAfter <= balBefore);
    }
}

