        // Restrict blockOffset to stay within admissible and non-zero future block range
        vm.assume(blockOffset > 0 && blockOffset < 256);
        // Set up: fund and lock in guess
        address actor = address(0x1234);
        vm.deal(actor, 2 ether);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(guessHash);
        // Move block.number past the locked block
        vm.roll(block.number + blockOffset);
        uint256 balanceBefore = address(c).balance;
        uint256 actorBalanceBefore = actor.balance;
        vm.prank(actor);
        c.settle();
        uint256 balanceAfter = address(c).balance;
        uint256 actorBalanceAfter = actor.balance;
        bytes32 answer = keccak256(abi.encodePacked(blockhash(block.number - blockOffset)));
