        // After lockInGuess the guess block is set to block.number + 1.
        // We need block.number > guesses[msg.sender].block,
        // so we advance by at least 2 (1 + delay where delay >= 1).
        vm.assume(blockDelay >= 1);
        vm.assume(blockDelay <= 256);

        address caller = address(uint160(uint256(keccak256(abi.encodePacked(guessHash, blockDelay)))));
        // Ensure caller has a non-zero, non-special address and not the contract itself
        vm.assume(caller != address(0) && caller != address(this) && caller != address(c));

        // Fund the contract with initial 1 ether via constructor; give caller 2 ether for lockInGuess.
        vm.deal(caller, 2 ether);

        // lockInGuess using our fuzzed hash
        vm.prank(caller);
        c.lockInGuess{value: 1 ether}(guessHash);

        // Advance blocks to satisfy require(block.number > guesses[msg.sender].block)
        vm.roll(block.number + blockDelay);

        uint256 callerBefore = caller.balance;
        // There is no try-catch because settle is non-payable and we rely on success/revert bool
        bool settled;
        vm.prank(caller);
        try c.settle() { settled = true; } catch { settled = false; }

        uint256 callerAfter = caller.balance;
        uint256 balanceDelta = callerAfter - callerBefore;

        // If settle succeeded, caller's balance must not increase when guess did NOT match answer.
        // Since we cannot read the answer directly (blockhash is an internal EVM opcode),
        // we enforce: the only way caller's balance can increase is if the guess matched.
        // The bug transfers 2 ether on mismatch, thus balanceDelta > 0 when guess != answer.
        // So invariant: if settle succeeded, (balanceDelta > 0) => (guess == answer).
        // We express this as: !settled || !(balanceDelta > 0) || (guess == answer).
        // But we cannot compute answer off-chain deterministically without knowing blockhash.
        // However, we can observe: For ANY hash, in the reference, balanceDelta > 0 IMPLIES guess == answer.
        // That is true in reference; bug breaks it because transfer occurs on mismatch.
        // But we cannot test "guess == answer" without reading guess (which we can) and answer.
        // We can read c.guesses(caller).guess via `c.guesses(caller).guess`? No, mapping is public,
        // but `guesses` is a mapping; we can call `c.guesses(caller)` which returns the struct.
        // Then we compute answer off-chain? We can't compute blockhash in Solidity for historical blocks.
        // Alternative invariant: In the correct contract, after settle() the caller's balance never increases unless the guess exactly equals answer, but we can't check answer. Instead,
        // we can check contract balance change: correct contract loses 2 ether only if guess == answer.
        // So contract balance never decreases if guess != answer. Bug decreases on mismatch.
        // We can check: If settled && (balanceDelta > 0), then contract balance must be < 1 ether (since it started with 1 ether, lockInGuess added 1, total 2).
        // Actually, we can assert: If settle succeeded and caller balance increased, then the contract's balance must have decreased by 2 ether.
        // In correct: balanceDelta > 0 => contractBalance == 0 (since transferred). Bug: balanceDelta > 0 on mismatch, and contractBalance still decreases by 2 ether. So this doesn't distinguish.

        // Let's use the fact that in correct contract, if the guess does NOT match, balanceDelta == 0.
        // So we assert: settled implies !(balanceDelta > 0) OR (some condition that indicates match).
        // But we cannot reliably know match without computing blockhash.
        // However, we can guarantee that at least one caller will have mismatch if fuzzer provides any hash,
        // and the property "balanceDelta == 0 if guess != answer" is always true in reference.
        // So the universal statement "for all inputs, settled and balanceDelta > 0 implies guess == answer"
        // is equivalent to "settled and guess != answer implies balanceDelta == 0".
        // Since we can read guess from the mapping, and we can compute answer using assembly? We could,
        // but the rules say only use public surface. blockhash is available as built-in in Solidity.
        // Yes! blockhash(uint blockNumber) returns bytes32. So we can compute answer in test!
        uint256 guessBlock = c.guesses(caller).block;
        // guessBlock was updated to block.number + 1 at lockInGuess, but after roll, we are at a later block.
        // Actually after lockInGuess, the contract set guesses[caller].block = block.number + 1 (of that time).
        // Then we rolled to block.number + blockDelay; now block.number is new, so guessBlock has the old target.
        // The contract's settle uses blockhash(guesses[msg.sender].block). We can compute that here.
        bytes32 answer = blockhash(guessBlock);
        // If guessBlock is too old (>256 blocks), blockhash returns 0, but that's fine; answer = 0 then.

        bytes32 originalGuess = c.guesses(caller).guess;

        // Now the invariant: settled => !(balanceDelta > 0) || (originalGuess == answer)
        assertTrue(!settled || balanceDelta == 0 || originalGuess == answer);
    }
}

